from __future__ import annotations

# Self-contained EuroLeague refresh runner.
# It restores the support Python scripts and seed fantasy profile data if they are missing,
# then runs the refresh pipeline. This prevents GitHub Actions from failing because a folder
# was not uploaded through the web UI.

import base64
import io
import subprocess
import sys
import tarfile
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
_PAYLOAD_B64 = """

"""

PIPELINE = [
    "update_active_profiles_prices.py",
    "create_euroleague_fantasy_dashboard.py",
    "patch_log_from_official_boxscore.py",
    "create_fantasheet_style_dashboard_fixed.py",
    "create_euroleague_advanced_context.py",
    "create_real_dvp_fix.py",
    "create_trilingual_dvp_pages.py",
    "apply_advanced_proj_pir_formula.py",
    "patch_top_projected_pir_card.py",
    "add_minutes_and_pirmin_cards.py",
    "add_shot_share_section.py",
    "finalize_euroleague_refresh.py",
    "patch_average_pir_card.py",
]


def restore_support_files() -> None:
    raw = base64.b64decode("".join(_PAYLOAD_B64.split()))
    with tarfile.open(fileobj=io.BytesIO(raw), mode="r:gz") as tar:
        tar.extractall(ROOT)
    print("Restored EuroLeague refresh support files under scripts/ and data/.")


def main() -> None:
    restore_support_files()
    for script in PIPELINE:
        path = ROOT / "scripts" / script
        if not path.exists() and script.endswith("_fixed.py"):
            path = ROOT / "scripts" / (script[: -len("_fixed.py")] + ".py")   # ako popravljeni korak nije uploadovan, koristi original
        if not path.exists():
            raise SystemExit(f"Missing required support script after restore: {path}")
        print(f"\n=== Running {script} ===", flush=True)
        subprocess.run([sys.executable, str(path)], cwd=str(ROOT), check=True)
    print("\nEuroLeague auto-refresh pipeline finished.")


if __name__ == "__main__":
    main()
